/**
 * We first generate a large number of ClassInfo instances for classes
 * that are no longer reachable.  Then queue up threads to all request
 * ClassInfo instances for new classes simultaneously to ensure that
 * clearing the old references wont deadlock the creation of new
 * instances.
 * <p>
 * GROOVY-8067
 */
@Test
public void testDeadlock() throws Exception {
    for (int i = 1; i <= DEADLOCK_TRIES; i++) {
        System.out.println("Test Number: " + i);
        generateGarbage();
        GCUtils.gc();
        attemptDeadlock(null);
    }
}

@Test
public void testRequestsForSameClassInfo() throws Exception {
    Class<?> newClass = createRandomClass();
    for (int i = 1; i <= DEADLOCK_TRIES; i++) {
        System.out.println("Test Number: " + i);
        generateGarbage();
        GCUtils.gc();
        attemptDeadlock(newClass);
    }
    ClassInfo newClassInfo = ClassInfo.getClassInfo(newClass);
    for (ClassInfo ci : ClassInfo.getAllClassInfo()) {
        if (ci.getTheClass() == newClass && ci != newClassInfo) {
            fail("Found multiple ClassInfo instances for class");
        }
    }
}

@Test
public void testLeak() {
    assertFalse(Boolean.getBoolean("groovy.use.classvalue"));
    for (int i = 0; i < NUM_OBJECTS; i++) {
        GroovyClassLoader gcl = new GroovyClassLoader();
        Class scriptClass = gcl.parseClass("int myvar = " + i);
        ClassInfo ci = ClassInfo.getClassInfo(scriptClass);
        Reference<ClassLoader> classLoaderRef = new WeakReference<ClassLoader>(gcl, classLoaderQueue);
        Reference<Class<?>> classRef = new WeakReference<Class<?>>(scriptClass, classQueue);
        Reference<ClassInfo> classInfoRef = new WeakReference<ClassInfo>(ci, classInfoQueue);
        refList.add(classLoaderRef);
        refList.add(classRef);
        refList.add(classInfoRef);
        gcl = null;
        scriptClass = null;
        ci = null;
        GCUtils.gc();
    }
    // Add new class to help evict the last collected entry
    GroovyClassLoader gcl = new GroovyClassLoader();
    Class scriptClass = gcl.parseClass("int myvar = 7777");
    ClassInfo ci = ClassInfo.getClassInfo(scriptClass);
    GCUtils.gc();
    // All objects should have been collected
    assertEquals("GroovyClassLoaders not collected by GC", NUM_OBJECTS, queueSize(classLoaderQueue));
    assertEquals("Script Classes not collected by GC", NUM_OBJECTS, queueSize(classQueue));
    int ciSize = queueSize(classInfoQueue);
    assertEquals("ClassInfo objects [" + ciSize + "] collected by GC, expected [" + NUM_OBJECTS + "]", NUM_OBJECTS, ciSize);
}

@Test
public void testQueueRemovesCollectedEntries() {
    // Keep a hardref so we can test get later
    List<Object> elements = populate();
    assertEquals("should contain all entries", ENTRY_COUNT, queue.values().size());
    Object o = elements.get(ENTRY_COUNT / 2);
    assertTrue("should contain an element", queue.values().contains(o));
    o = null;
    elements.remove(0);
    GCUtils.gc();
    assertEquals("should have one less element", ENTRY_COUNT - 1, queue.values().size());
    elements.clear();
    GCUtils.gc();
    // Add an entries to force ReferenceManager.removeStaleEntries
    Object last = new Object();
    queue.add(last);
    assertEquals("should only contain last added", 1, queue.values().size());
}

